begin;
insert into auth.users(id,email,raw_user_meta_data)select ('40000000-0000-4000-8000-00000000000'||n)::uuid,'evidence'||n||'@example.test',jsonb_build_object('username','evidence_'||n)from generate_series(1,4)n;
insert into public.circles(id,creator_id,name)values('40000000-0000-4000-8000-000000000010','40000000-0000-4000-8000-000000000001','Evidence crew');
insert into public.memberships(circle_id,user_id)select '40000000-0000-4000-8000-000000000010',id from public.profiles where username in('evidence_1','evidence_2','evidence_3');
insert into public.challenges(id,circle_id,created_by,rules,rules_hash,status)values('40000000-0000-4000-8000-000000000011','40000000-0000-4000-8000-000000000010','40000000-0000-4000-8000-000000000001','{"timezone":"UTC","capturePolicy":"camera_or_upload"}','test-hash','active');
insert into public.challenge_participants(challenge_id,user_id,status,rules_hash)select '40000000-0000-4000-8000-000000000011',user_id,'accepted','test-hash'from public.memberships where circle_id='40000000-0000-4000-8000-000000000010';
insert into public.daily_obligations(id,challenge_id,user_id,local_date,deadline_at)values('40000000-0000-4000-8000-000000000012','40000000-0000-4000-8000-000000000011','40000000-0000-4000-8000-000000000001',(clock_timestamp()at time zone'UTC')::date,clock_timestamp()+interval'1 hour');
create function pg_temp.assert_ok(value boolean,msg text)returns void language plpgsql as $$begin if value is not true then raise exception '%',msg;end if;end;$$;
create function pg_temp.must_fail(q text)returns void language plpgsql as $$declare failed boolean:=false;begin begin execute q;exception when others then failed:=true;end;if not failed then raise exception 'Expected failure: %',q;end if;end;$$;
grant execute on function pg_temp.assert_ok(boolean,text),pg_temp.must_fail(text)to authenticated,anon;
set local role authenticated;
do $$declare p jsonb:='{"challengeId":"40000000-0000-4000-8000-000000000011","obligationId":"40000000-0000-4000-8000-000000000012","source":"camera","note":"Reading notes"}';s jsonb;r jsonb;
begin
 perform set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000002',true);
 perform pg_temp.must_fail(format('select public.stakeup_evidence(''reserve'',%L)',p));
 perform set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000001',true);
 s:=public.stakeup_evidence('reserve',p);
 perform pg_temp.assert_ok(s->>'id'=public.stakeup_evidence('reserve',p)->>'id','Reservation not idempotent');
 p:=p||jsonb_build_object('proofId',s->>'id');
 perform pg_temp.must_fail(format('select public.stakeup_evidence(''finish'',%L)',p));
 perform pg_temp.must_fail('insert into storage.objects(bucket_id,name)values(''evidence'',''forged.jpg'')');
 insert into storage.objects(bucket_id,name)values('evidence',s->>'path');
 r:=public.stakeup_evidence('finish',p||'{"review":{"recommendation":"accepted"}}');
 perform pg_temp.assert_ok(r->>'status'='ai_reviewed'and r->'review'->>'provider'='development-mock-v1','Client forged AI decision');
 perform pg_temp.must_fail(format('select public.stakeup_evidence(''vote'',%L)',p||'{"decision":"accept","reason":"My own proof"}'));
 perform set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000002',true);
 r:=public.stakeup_evidence('vote',p||'{"decision":"reject","reason":"Irrelevant evidence"}');
 perform pg_temp.assert_ok(r->>'status'='ai_reviewed','Single rejection decided outcome');
 perform pg_temp.must_fail(format('select public.stakeup_evidence(''vote'',%L)',p||'{"decision":"accept","reason":"Changed vote"}'));
 perform set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000003',true);
 r:=public.stakeup_evidence('vote',p||'{"decision":"reject","reason":"Not the requested evidence"}');
 perform pg_temp.assert_ok(r->>'status'='rejected','Quorum rejection failed');
 perform set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000001',true);
 r:=public.stakeup_evidence('dispute',p||'{"reason":"Please consider the notes in my photo"}');
 perform pg_temp.assert_ok(r->>'status'='disputed','Owner appeal failed');
 perform set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000002',true);
 r:=public.stakeup_evidence('vote',p||'{"decision":"accept","reason":"Notes are relevant"}');
 perform pg_temp.assert_ok(r->>'status'='disputed','Single voter resolved dispute');
 perform set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000003',true);
 r:=public.stakeup_evidence('vote',p||'{"decision":"accept","reason":"Context explains the photo"}');
 perform pg_temp.assert_ok(r->>'status'='accepted','Dispute resolution failed');
 perform pg_temp.assert_ok(jsonb_array_length(r->'votes')=4,'Review history lost');
 perform pg_temp.must_fail('update public.evidence_submissions set status=''accepted''');
 perform set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000004',true);
 perform pg_temp.assert_ok((select count(*)=0 from public.evidence_submissions),'Outsider read proof');
 perform pg_temp.assert_ok((select count(*)=0 from public.evidence_votes),'Outsider read votes');
 perform pg_temp.assert_ok((select count(*)=0 from public.evidence_events),'Outsider read audit');
 perform pg_temp.assert_ok((select count(*)=0 from storage.objects where bucket_id='evidence'),'Outsider read private photos');
 perform pg_temp.must_fail(format('select public.stakeup_evidence(''photo'',%L)',p));
end;$$;
reset role;
set local role anon;
select pg_temp.must_fail('select public.stakeup_evidence(''list'',''{}'')');
rollback;
